1	syntax = "proto3";
2	
3	package memos.api.v1;
4	
5	import "api/v1/common.proto";
6	import "google/api/annotations.proto";
7	import "google/api/client.proto";
8	import "google/api/field_behavior.proto";
9	import "google/api/resource.proto";
10	import "google/protobuf/empty.proto";
11	import "google/protobuf/field_mask.proto";
12	import "google/protobuf/timestamp.proto";
13	import "google/type/color.proto";
14	
15	option go_package = "gen/api/v1";
16	
17	service UserService {
18	  // ListUsers returns a list of users.
19	  rpc ListUsers(ListUsersRequest) returns (ListUsersResponse) {
20	    option (google.api.http) = {get: "/api/v1/users"};
21	  }
22	
23	  // BatchGetUsers returns active users by usernames.
24	  rpc BatchGetUsers(BatchGetUsersRequest) returns (BatchGetUsersResponse) {
25	    option (google.api.http) = {
26	      post: "/api/v1/users:batchGet"
27	      body: "*"
28	    };
29	  }
30	
31	  // GetUser gets a user by username.
32	  // Format: users/{username} (e.g., users/steven)
33	  rpc GetUser(GetUserRequest) returns (User) {
34	    option (google.api.http) = {get: "/api/v1/{name=users/*}"};
35	    option (google.api.method_signature) = "name";
36	  }
37	
38	  // CreateUser creates a new user.
39	  rpc CreateUser(CreateUserRequest) returns (User) {
40	    option (google.api.http) = {
41	      post: "/api/v1/users"
42	      body: "user"
43	    };
44	    option (google.api.method_signature) = "user";
45	  }
46	
47	  // UpdateUser updates a user.
48	  rpc UpdateUser(UpdateUserRequest) returns (User) {
49	    option (google.api.http) = {
50	      patch: "/api/v1/{user.name=users/*}"
51	      body: "user"
52	    };
53	    option (google.api.method_signature) = "user,update_mask";
54	  }
55	
56	  // DeleteUser deletes a user.
57	  rpc DeleteUser(DeleteUserRequest) returns (google.protobuf.Empty) {
58	    option (google.api.http) = {delete: "/api/v1/{name=users/*}"};
59	    option (google.api.method_signature) = "name";
60	  }
61	
62	  // ListAllUserStats returns statistics for all users.
63	  rpc ListAllUserStats(ListAllUserStatsRequest) returns (ListAllUserStatsResponse) {
64	    option (google.api.http) = {get: "/api/v1/users:stats"};
65	  }
66	
67	  // GetUserStats returns statistics for a specific user.
68	  rpc GetUserStats(GetUserStatsRequest) returns (UserStats) {
69	    option (google.api.http) = {get: "/api/v1/{name=users/*}:getStats"};
70	    option (google.api.method_signature) = "name";
71	  }
72	
73	  // GetUserSetting returns the user setting.
74	  rpc GetUserSetting(GetUserSettingRequest) returns (UserSetting) {
75	    option (google.api.http) = {get: "/api/v1/{name=users/*/settings/*}"};
76	    option (google.api.method_signature) = "name";
77	  }
78	
79	  // UpdateUserSetting updates the user setting.
80	  rpc UpdateUserSetting(UpdateUserSettingRequest) returns (UserSetting) {
81	    option (google.api.http) = {
82	      patch: "/api/v1/{setting.name=users/*/settings/*}"
83	      body: "setting"
84	    };
85	    option (google.api.method_signature) = "setting,update_mask";
86	  }
87	
88	  // ListUserSettings returns a list of user settings.
89	  rpc ListUserSettings(ListUserSettingsRequest) returns (ListUserSettingsResponse) {
90	    option (google.api.http) = {get: "/api/v1/{parent=users/*}/settings"};
91	    option (google.api.method_signature) = "parent";
92	  }
93	
94	  // ListLinkedIdentities returns a list of linked SSO identities for a user.
95	  rpc ListLinkedIdentities(ListLinkedIdentitiesRequest) returns (ListLinkedIdentitiesResponse) {
96	    option (google.api.http) = {get: "/api/v1/{parent=users/*}/linkedIdentities"};
97	    option (google.api.method_signature) = "parent";
98	  }
99	
100	  // CreateLinkedIdentity links an SSO identity to the authenticated user.
101	  rpc CreateLinkedIdentity(CreateLinkedIdentityRequest) returns (LinkedIdentity) {
102	    option (google.api.http) = {
103	      post: "/api/v1/{parent=users/*}/linkedIdentities"
104	      body: "*"
105	    };
106	    option (google.api.method_signature) = "parent,idp_name";
107	  }
108	
109	  // GetLinkedIdentity gets a linked SSO identity for a user.
110	  rpc GetLinkedIdentity(GetLinkedIdentityRequest) returns (LinkedIdentity) {
111	    option (google.api.http) = {get: "/api/v1/{name=users/*/linkedIdentities/*}"};
112	    option (google.api.method_signature) = "name";
113	  }
114	
115	  // DeleteLinkedIdentity unlinks an SSO identity from a user.
116	  rpc DeleteLinkedIdentity(DeleteLinkedIdentityRequest) returns (google.protobuf.Empty) {
117	    option (google.api.http) = {delete: "/api/v1/{name=users/*/linkedIdentities/*}"};
118	    option (google.api.method_signature) = "name";
119	  }
120	
121	  // ListPersonalAccessTokens returns a list of Personal Access Tokens (PATs) for a user.
122	  // PATs are long-lived tokens for API/script access, distinct from short-lived JWT access tokens.
123	  rpc ListPersonalAccessTokens(ListPersonalAccessTokensRequest) returns (ListPersonalAccessTokensResponse) {
124	    option (google.api.http) = {get: "/api/v1/{parent=users/*}/personalAccessTokens"};
125	    option (google.api.method_signature) = "parent";
126	  }
127	
128	  // CreatePersonalAccessToken creates a new Personal Access Token for a user.
129	  // The token value is only returned once upon creation.
130	  rpc CreatePersonalAccessToken(CreatePersonalAccessTokenRequest) returns (CreatePersonalAccessTokenResponse) {
131	    option (google.api.http) = {
132	      post: "/api/v1/{parent=users/*}/personalAccessTokens"
133	      body: "*"
134	    };
135	  }
136	
137	  // DeletePersonalAccessToken deletes a Personal Access Token.
138	  rpc DeletePersonalAccessToken(DeletePersonalAccessTokenRequest) returns (google.protobuf.Empty) {
139	    option (google.api.http) = {delete: "/api/v1/{name=users/*/personalAccessTokens/*}"};
140	    option (google.api.method_signature) = "name";
141	  }
142	
143	  // ListUserWebhooks returns a list of webhooks for a user.
144	  rpc ListUserWebhooks(ListUserWebhooksRequest) returns (ListUserWebhooksResponse) {
145	    option (google.api.http) = {get: "/api/v1/{parent=users/*}/webhooks"};
146	    option (google.api.method_signature) = "parent";
147	  }
148	
149	  // CreateUserWebhook creates a new webhook for a user.
150	  rpc CreateUserWebhook(CreateUserWebhookRequest) returns (UserWebhook) {
151	    option (google.api.http) = {
152	      post: "/api/v1/{parent=users/*}/webhooks"
153	      body: "webhook"
154	    };
155	    option (google.api.method_signature) = "parent,webhook";
156	  }
157	
158	  // UpdateUserWebhook updates an existing webhook for a user.
159	  rpc UpdateUserWebhook(UpdateUserWebhookRequest) returns (UserWebhook) {
160	    option (google.api.http) = {
161	      patch: "/api/v1/{webhook.name=users/*/webhooks/*}"
162	      body: "webhook"
163	    };
164	    option (google.api.method_signature) = "webhook,update_mask";
165	  }
166	
167	  // DeleteUserWebhook deletes a webhook for a user.
168	  rpc DeleteUserWebhook(DeleteUserWebhookRequest) returns (google.protobuf.Empty) {
169	    option (google.api.http) = {delete: "/api/v1/{name=users/*/webhooks/*}"};
170	    option (google.api.method_signature) = "name";
171	  }
172	
173	  // GetUserWebhookSigningSecret returns the signing secret for a webhook.
174	  // The secret is returned only through this explicit, owner-gated call; it is
175	  // never included in List/Create/Update responses.
176	  rpc GetUserWebhookSigningSecret(GetUserWebhookSigningSecretRequest) returns (GetUserWebhookSigningSecretResponse) {
177	    option (google.api.http) = {get: "/api/v1/{name=users/*/webhooks/*}:getSigningSecret"};
178	    option (google.api.method_signature) = "name";
179	  }
180	
181	  // ListUserNotifications lists notifications for a user.
182	  rpc ListUserNotifications(ListUserNotificationsRequest) returns (ListUserNotificationsResponse) {
183	    option (google.api.http) = {get: "/api/v1/{parent=users/*}/notifications"};
184	    option (google.api.method_signature) = "parent";
185	  }
186	
187	  // UpdateUserNotification updates a notification.
188	  rpc UpdateUserNotification(UpdateUserNotificationRequest) returns (UserNotification) {
189	    option (google.api.http) = {
190	      patch: "/api/v1/{notification.name=users/*/notifications/*}"
191	      body: "notification"
192	    };
193	    option (google.api.method_signature) = "notification,update_mask";
194	  }
195	
196	  // DeleteUserNotification deletes a notification.
197	  rpc DeleteUserNotification(DeleteUserNotificationRequest) returns (google.protobuf.Empty) {
198	    option (google.api.http) = {delete: "/api/v1/{name=users/*/notifications/*}"};
199	    option (google.api.method_signature) = "name";
200	  }
201	}
202	
203	message User {
204	  option (google.api.resource) = {
205	    type: "memos.api.v1/User"
206	    pattern: "users/{user}"
207	    name_field: "name"
208	    singular: "user"
209	    plural: "users"
210	  };
211	
212	  // The resource name of the user.
213	  // Format: users/{user}
214	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
215	
216	  // The role of the user.
217	  Role role = 2 [(google.api.field_behavior) = REQUIRED];
218	
219	  // Required. The unique username for login.
220	  string username = 3 [(google.api.field_behavior) = REQUIRED];
221	
222	  // Optional. The email address of the user.
223	  string email = 4 [(google.api.field_behavior) = OPTIONAL];
224	
225	  // Optional. The display name of the user.
226	  string display_name = 5 [(google.api.field_behavior) = OPTIONAL];
227	
228	  // Optional. The avatar URL of the user.
229	  string avatar_url = 6 [(google.api.field_behavior) = OPTIONAL];
230	
231	  // Optional. The description of the user.
232	  string description = 7 [(google.api.field_behavior) = OPTIONAL];
233	
234	  // Input only. The password for the user.
235	  string password = 8 [(google.api.field_behavior) = INPUT_ONLY];
236	
237	  // The state of the user.
238	  State state = 9 [(google.api.field_behavior) = REQUIRED];
239	
240	  // Output only. The creation timestamp.
241	  google.protobuf.Timestamp create_time = 10 [(google.api.field_behavior) = OUTPUT_ONLY];
242	
243	  // Output only. The last update timestamp.
244	  google.protobuf.Timestamp update_time = 11 [(google.api.field_behavior) = OUTPUT_ONLY];
245	
246	  // User role enumeration.
247	  enum Role {
248	    ROLE_UNSPECIFIED = 0;
249	    // Admin role with system access.
250	    ADMIN = 2;
251	    // User role with limited access.
252	    USER = 3;
253	  }
254	}
255	
256	message ListUsersRequest {
257	  // Optional. The maximum number of users to return.
258	  // The service may return fewer than this value.
